function renderSync(){
  const source=scoped(CloudCallData.syncRecords),current=filters.sync,keyword=current.keyword.toLowerCase(),key=contextKey();
  const rows=source.filter(row=>(!keyword||`${row.objectName} ${row.objectType} ${configurationName(row)}`.toLowerCase().includes(keyword))&&(current.status==='全部状态'||row.status===current.status));
  pages.sync=Math.min(pages.sync,Math.max(1,Math.ceil(rows.length/pageSize)));
  return `<section class="platform-page sync-page">${ui.pageHeader('坐席配置记录','查看新增坐席、技能配置及成员调整的处理结果；资料有误时可修改后重新提交。')}${filterPanel('sync','坐席 / 配置类型')}${shell('sync',rows,[
    {key:'objectName',label:'坐席 / 对象'},{key:'objectType',label:'配置类型',render:(v,r)=>esc(configurationName(r))},{key:'status',label:'处理结果',render:v=>ui.status(v)},
    {key:'failureReason',label:'处理说明',render:(v,r)=>`<span class="${r.status==='失败'?'danger-text':''}">${esc(recordReason(r))}</span>`},
    {key:'updatedAt',label:'更新时间'},
    {key:'syncId',label:'操作',className:'action-column',render:(v,r)=>`<div class="table-actions">${mayCorrectRecord(r)?`<button onclick="${command('retry',v,key)}">修改资料</button>`:''}<button onclick="${command('openSyncRecord',v,key)}">${r.status==='成功'?'查看记录':'查看原因'}</button></div>`}
  ],'', '记录新增坐席和技能配置的处理结果，保留原失败原因与后续提交记录。')}</section>`;
}

table_implementation.source_quote:
function table(columns, rows, options) {
  const opts = options || {};
  // 云呼叫列表统一编号；数据副本保留调用方对象，现有序号列沿用页面规则。
  if(window.AppState?.get().activeDomain==='CLOUD_CONTACT_CENTER'&&opts.numbered!==false&&!columns.some(col=>col.label==='序号')){
    const offset=Number(opts.rowOffset)||0;
    columns=[{key:'__listSequence',label:'序号',width:'64px'},...columns];
    rows=rows.map((row,index)=>({...row,__listSequence:offset+index+1}));
  }
  const head = columns.map(col => `<th class="${escape(col.className || '')}"${col.width ? ` style="width:${escape(col.width)}"` : ''}>${typeof col.headerRender === 'function' ? col.headerRender() : escape(col.label)}${col.help ? help(col.help, col.label) : ''}</th>`).join('');
  const body = rows.length ? rows.map(row => `<tr>${columns.map(col => `<td class="${escape(col.className || '')}">${col.render ? col.render(row[col.key], row) : escape(row[col.key] == null ? '—' : ['callType','type','method'].includes(col.key) ? callTypeLabel(row[col.key]) : row[col.key])}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${columns.length}">${empty(opts.emptyText || '暂无数据', opts.emptyDetail)}</td></tr>`;
  return `<div class="table-card ${escape(opts.className || '')}"><div class="table-scroll"><table class="platform-table"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>${opts.footer || ''}</div>`;
}

escape_implementation_evidence.source_quote:
function escape(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}

